                target_cache,
                token,
                pos,
                target_config,
            );
            probs_buf.copy_from_slice(logits);
            softmax_scaled(probs_buf, 1.0 / target_config.temperature);
            let fallback = sample_from_distribution(probs_buf, rng);
            configurator.update(ctx, decision, 0.0);
            (vec![fallback], 1, decision)
        }
    }

