            if let Some(grid) = grid.filter(|g| !g.is_empty()) {
                grid.query_nearest(
                    npc.pos,
                    perception_radius,
                    |i| animals[i].pos,
                    |i| {
                        animals[i].alive
                            && matches!(
                                animals[i].snapshot.species,
                                super::super::animal::AnimalKind::Wolf
                                    | super::super::animal::AnimalKind::Eagle
                            )
                    },
                )
                .map(|(_, d_sq)| d_sq)
                .unwrap_or(f32::INFINITY)
            } else {
                let mut nearest = f32::INFINITY;
                for animal in animals {
                    if !animal.alive { continue; }
                    let is_predator = matches!(
                        animal.snapshot.species,
                        super::super::animal::AnimalKind::Wolf | super::super::animal::AnimalKind::Eagle
                    );
                    if !is_predator { continue; }
                    let dx = animal.pos.x - npc.pos.x;
                    let dy = animal.pos.y - npc.pos.y;
                    let dist_sq = dx * dx + dy * dy;
                    if dist_sq < perception_radius * perception_radius && dist_sq < nearest {
                        nearest = dist_sq;
                    }
                }
                nearest
            }
        }
    }

